  // Écris ton code ici.
}

lessons.solution:
function reachableOnes(grid, y, x) {
  const stack = [[y, x]];
  const seen = new Set();
  while (stack.length > 0) {
    const [cy, cx] = stack.pop();
    if (
      cy < 0 ||
      cy >= grid.length ||
      cx < 0 ||
      cx >= grid[cy].length ||
      grid[cy][cx] !== 1
    )
      continue;
    const key = String(cy) + "," + String(cx);
    if (seen.has(key)) continue;
    seen.add(key);
    for (const [dy, dx] of [
      [-1, 0],
      [1, 0],
      [0, -1],
      [0, 1],
    ])
      stack.push([cy + dy, cx + dx]);
  }
  return seen.size;
}

