  return "timeout";
}

lessons.solution:
async function timedWinner(delays, limit) {
  const timers = [];
  const jobs = delays.map(
    (delay, index) =>
      new Promise((resolve) => {
        timers.push(setTimeout(() => resolve(index), delay));
      }),
  );
  jobs.push(
    new Promise((resolve) => {
      timers.push(setTimeout(() => resolve("timeout"), limit));
    }),
  );
  try {
    return await Promise.race(jobs);
  } finally {
    for (const timer of timers) clearTimeout(timer);
  }
}

