lessons.solution:
async function retryValue(failures, limit) {
  let attempts = 0;
  const operation = () =>
    ++attempts <= failures
      ? Promise.reject(new Error("échec"))
      : Promise.resolve("ok");
  for (let i = 0; i < limit; i++) {
    try {
      return await operation();
    } catch (error) {}
  }
  return "échec";
}

