function cloneFrozenReport(value) {
  return { copy: value, independent: false, frozen: false };
}

lessons.solution:
function cloneFrozenReport(value) {
  function clone(x) {
    if (x === null || typeof x !== "object") return x;
    const out = Array.isArray(x)
      ? x.map(clone)
      : Object.fromEntries(Object.entries(x).map(([k, v]) => [k, clone(v)]));
    return Object.freeze(out);
  }
  const copy = clone(value);
  function independent(a, b) {
    return (
      a === null ||
      typeof a !== "object" ||
      (a !== b && Object.keys(a).every((k) => independent(a[k], b[k])))
    );
  }
  function frozen(x) {
    return (
      x === null ||
      typeof x !== "object" ||
      (Object.isFrozen(x) && Object.values(x).every(frozen))
    );
  }
  return { copy, independent: independent(value, copy), frozen: frozen(copy) };
}

lessons.starter:
function deepEqual(a, b) {
  return false;
}

lessons.solution:
function deepEqual(a, b) {
  if (a === b) return true;
  if (
    a === null ||
    b === null ||
    typeof a !== "object" ||
    typeof b !== "object"
  )
    return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const keys = Object.keys(a);
  return (
    keys.length === Object.keys(b).length &&
    keys.every((key) => Object.hasOwn(b, key) && deepEqual(a[key], b[key]))
  );
}

