lessons.solution:
function deepFind(root, path) {
  let current = root;
  for (const key of path) {
    if (
      current === null ||
      typeof current !== "object" ||
      !Object.hasOwn(current, key)
    )
      return null;
    current = current[key];
  }
  return current;
}

