lessons.solution:
function readProxy(obj, keys) {
  const proxy = new Proxy(obj, {
    get(target, key, receiver) {
      if (typeof key === "string" && !Object.hasOwn(target, key))
        return "absent";
      return Reflect.get(target, key, receiver);
    },
  });
  return keys.map((key) => proxy[key]);
}

