lessons.solution:
function upperKeys(value) {
  if (value === null || typeof value !== "object") return value;
  if (Array.isArray(value)) return value.map(upperKeys);
  return Object.fromEntries(
    Object.entries(value).map(([key, item]) => [
      key.toUpperCase(),
      upperKeys(item),
    ]),
  );
}
